  border-radius: 12px;
  font-size: 15px;
  font-weight: 600;
  z-index: 9999;
  opacity: 0;
  transition: all 0.3s;
  pointer-events: none;
  box-shadow: 0 4px 16px rgba(0,0,0,0.2);
  max-width: 90%;
  text-align: center;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.success { background: var(--green); }
.toast.error { background: var(--red); }
.toast.warn { background: var(--orange); }

/* ===== 模态框 ===== */
.modal-overlay {
  display: none;
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1000;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.modal-overlay.show { display: flex; }
.modal {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 28px;
  max-width: 420px;
  width: 100%;
  box-shadow: var(--shadow-lg);
}
.modal h3 { font-size: 20px; font-weight: 800; margin-bottom: 16px; text-align: center; }
.modal p { color: var(--text-light); margin-bottom: 20px; text-align: center; font-size: 15px; }
.modal-actions { display: flex; gap: 12px; }
.modal-actions .btn { flex: 1; }

/* ===== 庆祝动画 ===== */
.confetti-container {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  pointer-events: none;
  z-index: 9998;
  overflow: hidden;
}
.confetti-piece {
  position: absolute;
  width: 10px;
  height: 10px;
  top: -10px;
  animation: confetti-fall linear forwards;
}
@keyframes confetti-fall {
  0% { transform: translateY(0) rotate(0); opacity: 1; }
  100% { transform: translateY(110vh) rotate(720deg); opacity: 0.5; }
}

/* ===== 数据量提醒 ===== */
.data-reminder {
  background: linear-gradient(135deg, #FFF9E6, #FFF3CC);
  border: 1px solid #FFE082;
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  margin-bottom: 16px;
  font-size: 14px;
  color: #8B6914;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}
.data-reminder svg { width: 20px; height: 20px; flex-shrink: 0; }

/* ===== 隐藏 ===== */
.hidden { display: none !important; }

/* ===== 响应式 ===== */
@media (max-width: 768px) {
  .header { padding: 14px 16px 12px; }
  .header-title { font-size: 18px; }
  .header-actions { gap: 6px; }
  .btn-backup { padding: 7px 12px; font-size: 12px; }
  .container { padding: 12px 12px 90px; }
  .practice-options { grid-template-columns: 1fr; }
  .flip-word { font-size: 34px; }
  .flip-card { height: 240px; }
  .stat-grid { grid-template-columns: repeat(2, 1fr); }
  .module-nav-item { padding: 10px 14px; font-size: 14px; }
  .reward-form input[type="number"] { max-width: 80px; }
  .history-table { font-size: 12px; }
  .history-table th, .history-table td { padding: 8px 6px; }
}
@media (max-width: 480px) {
  .word-english { font-size: 17px; }
  .word-item { padding: 12px; }
  .parent-gate-input input { width: 50px; height: 50px; font-size: 24px; }
}

/* ===== 空状态 ===== */
.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--text-lighter);
}
.empty-state svg { width: 48px; height: 48px; margin-bottom: 12px; }
