var LEVELS = [
  { min: 0, max: 19, name: '英语小萌新', color: '#A8D8B9', icon: 'M12 2C8 2 5 5 5 9c0 3 2 5 4 6v5h6v-5c2-1 4-3 4-6 0-4-3-7-7-7z' },
  { min: 20, max: 49, name: '单词学徒', color: '#4A90D9', icon: 'M12 2l2.4 4.8L19 8l-4 3.5L16 16l-4-2.5L8 16l1-4.5L5 8l4.6-1.2z' },
  { min: 50, max: 99, name: '词汇达人', color: '#9B59B6', icon: 'M5 8h14l-1 12H6L5 8zM9 4h6v4H9z' },
  { min: 100, max: 199, name: '英语小达人', color: '#FF9F43', icon: 'M12 15c-5 0-9-3-9-6V6h18v3c0 3-4 6-9 6z' },
  { min: 200, max: 99999, name: '英语之星', color: '#FF6B6B', icon: 'M12 2l3 6 6 1-4.5 4 1 6-5.5-3-5.5 3 1-6L3 9l6-1z' }
];

var DEFAULT_REWARDS = [
  { id: 1, name: '看动画片30分钟', cost: 30, claimed: false },
  { id: 2, name: '吃一次小零食', cost: 20, claimed: false },
  { id: 3, name: '去公园玩一次', cost: 50, claimed: false },
  { id: 4, name: '买一个小玩具', cost: 100, claimed: false }
];

var currentMode = 'child';
var currentTab = 'daily';
var practiceState = { active: false, current: 0, questions: [], score: 0, correct: 0 };
var currentCardIdx = 0;
var todayWordsData = [];
var overdueWords = [];

// ======== 数据读写 ========
function loadData(key, defaultValue) {
  try {
    var raw = localStorage.getItem(key);
    if (raw === null || raw === undefined) return defaultValue;
    return JSON.parse(raw);
  } catch(e) {
    return defaultValue;
  }
}

function saveData(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch(e) {
    showToast('保存失败，可能存储空间已满', 'error');
    return false;
  }
}

// ======== 日期工具 ========
function getTodayStr() {
  var d = new Date();
  var y = d.getFullYear();
  var m = String(d.getMonth() + 1).padStart(2, '0');
  var day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

function getYesterdayStr() {
  var d = new Date();
  d.setDate(d.getDate() - 1);
  var y = d.getFullYear();
  var m = String(d.getMonth() + 1).padStart(2, '0');
  var day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

function formatDate(dateStr) {
  if (!dateStr) return '';
  var parts = dateStr.split('-');
  return parts[1] + '月' + parts[2] + '日';
}

// ======== 初始化 ========
function init() {
  var settings = loadData(KEYS.settings, null);
  if (!settings) {
    // 首次运行，初始化示例数据
    settings = {
      password: '',
      dailyGoal: 5,
      childName: '宝贝',
      createdAt: getTodayStr()
    };
    saveData(KEYS.settings, settings);
    seedSampleData();
  }

  // 分配今日单词
  assignDailyWords();

  // 检查逾期
  checkOverdue();

  // 渲染
  renderTodaySection();
  renderTab();
  checkDataReminder();
}

function seedSampleData() {
  // 初始化单词库
  saveData(KEYS.words, WORD_BANK);

  // 初始化积分
  var points = {
    total: 35,
    history: [
      { date: getYesterdayStr(), action: '学会5个单词', points: 10 },
      { date: getYesterdayStr(), action: '组词练习得分80', points: 5 },
      { date: getYesterdayStr(), action: '音标卡片复习', points: 5 },
      { date: getYesterdayStr(), action: '连续学习奖励', points: 15 }
    ],
    rewards: DEFAULT_REWARDS.slice()
  };
  saveData(KEYS.points, points);

  // 初始化进度 - 昨天只学了3个（2个逾期）
  var yesterday = getYesterdayStr();
  var progress = {};
  progress[yesterday] = {
    assigned: [6, 7, 8, 9, 10], // apple, banana, milk, bread, egg
    learned: [6, 7, 8], // 只学了3个，9和10逾期
    practiceScore: 80,
    practiceDone: true,
    pointsEarned: 15
  };
  saveData(KEYS.progress, progress);

  // 初始化历史记录
  var records = [
    { date: yesterday, wordsLearned: 3, practiceScore: 80, pointsEarned: 15, totalPoints: 35 }
  ];
  saveData(KEYS.records, records);
}

// ======== 分配每日单词 ========
function assignDailyWords() {
  var progress = loadData(KEYS.progress, {});
  var today = getTodayStr();

  if (progress[today] && progress[today].assigned) {
    todayWordsData = progress[today].assigned.map(function(id) {
      return WORD_BANK.find(function(w) { return w.id === id; });
    }).filter(Boolean);
    return;
  }

  // 轮换分配：根据已有天数决定偏移量
  var dayCount = Object.keys(progress).length;
  var offset = (dayCount * 5) % WORD_BANK.length;
  var assigned = [];
  for (var i = 0; i < 5; i++) {
    assigned.push(WORD_BANK[(offset + i) % WORD_BANK.length].id);
  }

  progress[today] = {
    assigned: assigned,
    learned: [],
    practiceScore: 0,
    practiceDone: false,
    pointsEarned: 0
  };
  saveData(KEYS.progress, progress);

  todayWordsData = assigned.map(function(id) {
    return WORD_BANK.find(function(w) { return w.id === id; });
  }).filter(Boolean);
}

// ======== 检查逾期 ========
function checkOverdue() {
  var progress = loadData(KEYS.progress, {});
  var today = getTodayStr();
  var yesterday = getYesterdayStr();

  overdueWords = [];

  // 检查昨天未学完的单词
  if (progress[yesterday]) {
    var yAssigned = progress[yesterday].assigned || [];
    var yLearned = progress[yesterday].learned || [];
    var unlearned = yAssigned.filter(function(id) { return yLearned.indexOf(id) === -1; });

    unlearned.forEach(function(id) {
      var w = WORD_BANK.find(function(w) { return w.id === id; });
      if (w) overdueWords.push(w);
    });

    // 把昨天没学完的单词顺延到今天
    if (unlearned.length > 0 && progress[today]) {
      var todayAssigned = progress[today].assigned || [];
      // 把逾期的单词加到今天的列表前面
      unlearned.forEach(function(id) {
        if (todayAssigned.indexOf(id) === -1) {
          todayAssigned.unshift(id);
        }
      });
      // 确保今天最多有足够的单词（可能超过5个，因为有顺延的）
      progress[today].assigned = todayAssigned;
      saveData(KEYS.progress, progress);

      // 更新今天单词数据
      todayWordsData = todayAssigned.map(function(id) {
        return WORD_BANK.find(function(w) { return w.id === id; });
      }).filter(Boolean);
    }

    // 昨天的练习没做也算逾期
    if (!progress[yesterday].practiceDone) {
      // 标记为逾期练习
    }
  }
}

// ======== 渲染今日要处理 ========
function renderTodaySection() {
  var today = getTodayStr();
  var progress = loadData(KEYS.progress, {});
  var todayProg = progress[today] || { assigned: [], learned: [], practiceDone: false };
  var learnedCount = todayProg.learned ? todayProg.learned.length : 0;
  var totalCount = todayProg.assigned ? todayProg.assigned.length : 0;
  var overdueCount = overdueWords.length;

  var html = '';
  html += '<div class="today-header">';
  html += '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>';
  html += '今天要处理';
  html += '</div>';

  // 逾期项
  if (overdueCount > 0) {
    html += '<div class="today-item overdue">';
    html += '<div class="today-item-content">';
    html += '<div class="today-item-title">';
    html += '昨天没学完的单词 (' + overdueCount + '个) <span class="overdue-badge">逾期</span>';
    html += '</div>';
