  // 今日单词
  html += '<div class="today-item">';
  html += '<div class="today-item-content">';
  html += '<div class="today-item-title">今日单词任务 (' + learnedCount + '/' + totalCount + ')</div>';
  html += '<div class="today-item-desc">学完今天' + totalCount + '个单词 + 10积分</div>';
  html += '</div>';
  html += '<button class="btn btn-primary" onclick="switchTab(\'daily\')">' + (learnedCount < totalCount ? '去学' : '已完成') + '</button>';
  html += '</div>';

  // 今日练习
  html += '<div class="today-item">';
  html += '<div class="today-item-content">';
  html += '<div class="today-item-title">今日组词练习 ' + (todayProg.practiceDone ? '<span style="color:var(--green)">已完成</span>' : '待完成') + '</div>';
  html += '<div class="today-item-desc">完成练习 + 积分奖励</div>';
  html += '</div>';
  html += '<button class="btn btn-green" onclick="switchTab(\'practice\')">' + (todayProg.practiceDone ? '复习' : '去做') + '</button>';
  html += '</div>';

  // 进度条
  var allDone = learnedCount >= totalCount && todayProg.practiceDone;
  html += '<div class="today-progress">';
  if (allDone) {
    html += '今天的任务全部完成啦！太棒了！';
  } else {
    html += '今日进度：单词 ' + learnedCount + '/' + totalCount + '，练习 ' + (todayProg.practiceDone ? '完成' : '未完成');
  }
  html += '</div>';

  document.getElementById('today-section').innerHTML = html;
}

// ======== 模块切换 ========
function switchTab(tab) {
  currentTab = tab;
  var items = document.querySelectorAll('.module-nav-item');
  items.forEach(function(el) { el.classList.remove('active'); });
  var active = document.querySelector('.module-nav-item[data-tab="' + tab + '"]');
  if (active) active.classList.add('active');
  renderTab();
}

function renderTab() {
  var container = document.getElementById('tab-content');
  switch(currentTab) {
    case 'daily': container.innerHTML = renderDailyWords(); break;
    case 'cards': container.innerHTML = renderPhoneticCards(); break;
    case 'practice': container.innerHTML = renderPractice(); break;
    case 'points': container.innerHTML = renderPoints(); break;
  }
  // 练习模块需要绑定事件
  if (currentTab === 'practice' && !practiceState.active) {
    // 等待用户点击开始
  }
}

