function toggleWordLearned(wordId) {
  var today = getTodayStr();
  var progress = loadData(KEYS.progress, {});
  if (!progress[today]) progress[today] = { assigned: [], learned: [], practiceDone: false, pointsEarned: 0 };
  var learned = progress[today].learned || [];
  var idx = learned.indexOf(wordId);
  var wasLearned = idx !== -1;

  if (wasLearned) {
    learned.splice(idx, 1);
  } else {
    learned.push(wordId);
    speak(WORD_BANK.find(function(w) { return w.id === wordId; }).word);
  }
  progress[today].learned = learned;

  // 检查是否全部学完
  var totalCount = progress[today].assigned.length;
  if (learned.length >= totalCount && !progress[today].allLearnedRewarded) {
    addPoints(10, '学完今日' + totalCount + '个单词');
    progress[today].allLearnedRewarded = true;
    progress[today].pointsEarned = (progress[today].pointsEarned || 0) + 10;
    showToast('全部学完！+10 积分！', 'success');
    triggerConfetti();
  } else if (!wasLearned) {
    // 每学一个单词得1分
    addPoints(1, '学会单词 "' + WORD_BANK.find(function(w) { return w.id === wordId; }).word + '"');
    progress[today].pointsEarned = (progress[today].pointsEarned || 0) + 1;
  }

  saveData(KEYS.progress, progress);
  renderTodaySection();
  renderTab();
}

