// ======== 组词练习模块 ========
function renderPractice() {
  var today = getTodayStr();
  var progress = loadData(KEYS.progress, {});
  var todayProg = progress[today] || { practiceDone: false };

  if (!practiceState.active) {
    var html = '';
    html += '<div class="card">';
    html += '<div class="card-title">';
    html += '<svg viewBox="0 0 24 24" fill="none" stroke="var(--green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>';
    html += '组词练习';
    html += '</div>';

    if (todayWordsData.length === 0) {
      html += '<div class="empty-state"><p>今天还没有单词，无法练习</p></div>';
      html += '</div>';
      return html;
    }

    html += '<div class="practice-intro">';
    html += '<h3>准备好了吗？</h3>';
    html += '<p>共 ' + todayWordsData.length + ' 道题，每题选一个正确答案</p>';
    html += '<p style="margin-top:8px">全对可得3星，80分以上2星，60分以上1星</p>';
    html += '</div>';

    if (todayProg.practiceDone) {
      html += '<div style="text-align:center;margin-bottom:16px">';
      html += '<span style="color:var(--green);font-weight:700;font-size:15px">今天的练习已完成，得分: ' + (todayProg.practiceScore || 0) + ' 分</span>';
      html += '<br><span style="font-size:13px;color:var(--text-light)">可以再做一次复习哦</span>';
      html += '</div>';
    }

    html += '<div style="text-align:center">';
    html += '<button class="btn btn-green btn-lg" onclick="startPractice()">';
    html += '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
    html += '开始练习';
    html += '</button>';
    html += '</div>';
    html += '</div>';
    return html;
  }

  // 练习进行中
  var q = practiceState.questions[practiceState.current];
  if (!q) return '<div class="card"><p>练习结束</p></div>';

  var html = '';
  html += '<div class="card">';
  html += '<div class="card-title">';
  html += '<svg viewBox="0 0 24 24" fill="none" stroke="var(--green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>';
  html += '组词练习 (第' + (practiceState.current + 1) + '/' + practiceState.questions.length + '题)';
  html += '</div>';

  // 进度点
  html += '<div class="practice-progress">';
  for (var i = 0; i < practiceState.questions.length; i++) {
    var cls = 'practice-dot';
    if (i < practiceState.current) cls += ' done';
    if (i === practiceState.current) cls += ' current';
    html += '<div class="' + cls + '"></div>';
  }
  html += '</div>';

  // 题目
  html += '<div class="practice-question">';
  html += '<div class="practice-question-text">' + q.question + '</div>';
  html += '<div class="practice-question-hint">' + q.hint + '</div>';
  html += '<div class="practice-options">';
  q.options.forEach(function(opt, i) {
    var cls = 'practice-option';
    if (q.answered) {
      cls += ' disabled';
      if (i === q.correctIdx) cls += ' correct';
      if (i === q.selectedIdx && i !== q.correctIdx) cls += ' wrong';
    }
    html += '<div class="' + cls + '" onclick="answerPractice(' + i + ')">' + opt + '</div>';
  });
  html += '</div>';
  html += '</div>';

  // 下一题按钮
  if (q.answered) {
    html += '<div style="text-align:center;margin-top:20px">';
    if (practiceState.current < practiceState.questions.length - 1) {
      html += '<button class="btn btn-primary btn-lg" onclick="nextQuestion()">下一题</button>';
    } else {
      html += '<button class="btn btn-green btn-lg" onclick="finishPractice()">查看成绩</button>';
    }
    html += '</div>';
  }

  html += '</div>';
  return html;
}

function startPractice() {
  // 生成题目
  var questions = [];
  todayWordsData.forEach(function(w) {
    // 题型1：填空题
    var blanked = w.sentence.replace(new RegExp(w.word, 'i'), '___');
    var options = [w.word];
    // 随机选3个干扰项
    var pool = WORD_BANK.filter(function(x) { return x.id !== w.id; });
    pool = shuffleArray(pool).slice(0, 3);
    pool.forEach(function(p) { options.push(p.word); });
    options = shuffleArray(options);
    var correctIdx = options.indexOf(w.word);

    questions.push({
      question: blanked,
      hint: '选择正确的单词填空',
      options: options,
      correctIdx: correctIdx,
      selectedIdx: -1,
      answered: false
    });
  });

  practiceState = { active: true, current: 0, questions: questions, score: 0, correct: 0 };
  renderTab();
}

function shuffleArray(arr) {
  var a = arr.slice();
  for (var i = a.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}

function answerPractice(idx) {
  var q = practiceState.questions[practiceState.current];
  if (q.answered) return;
  q.answered = true;
  q.selectedIdx = idx;
  if (idx === q.correctIdx) {
    practiceState.correct++;
    practiceState.score += 20;
    speak(q.options[idx]);
    showToast('回答正确！', 'success');
  } else {
    showToast('正确答案是：' + q.options[q.correctIdx], 'error');
  }
  renderTab();
}

function nextQuestion() {
  if (practiceState.current < practiceState.questions.length - 1) {
    practiceState.current++;
    renderTab();
  }
}

function finishPractice() {
  practiceState.active = false;
  var total = practiceState.questions.length;
  var score = practiceState.score;
  var correct = practiceState.correct;
  var percent = Math.round(correct / total * 100);

  // 保存练习成绩
  var today = getTodayStr();
  var progress = loadData(KEYS.progress, {});
  if (!progress[today]) progress[today] = { assigned: [], learned: [], practiceDone: false, pointsEarned: 0 };
  progress[today].practiceScore = percent;
  progress[today].practiceDone = true;

  // 计算积分
  var points = 0;
  if (percent >= 80) points = 10;
  else if (percent >= 60) points = 5;
  else points = 2;

  if (!progress[today].practiceRewarded) {
    progress[today].practiceRewarded = true;
    progress[today].pointsEarned = (progress[today].pointsEarned || 0) + points;
    addPoints(points, '组词练习得分' + percent);
    saveData(KEYS.progress, progress);
  } else {
    saveData(KEYS.progress, progress);
  }

  // 更新记录
  updateRecords(percent);

  // 显示结果
  var stars = percent >= 80 ? 3 : (percent >= 60 ? 2 : (percent >= 40 ? 1 : 0));

  var html = '';
  html += '<div class="card">';
  html += '<div class="practice-result">';
  html += '<div class="practice-result-score">' + percent + '分</div>';
  html += '<div class="practice-result-label">答对 ' + correct + '/' + total + ' 题</div>';
  html += '<div class="practice-result-stars">';
  for (var i = 0; i < 3; i++) {
    var cls = i < stars ? 'earned' : '';
    html += '<svg class="practice-star ' + cls + '" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>';
  }
  html += '</div>';
  html += '<div style="font-size:16px;color:var(--text-light);margin-bottom:20px">+' + points + ' 积分</div>';
  html += '<button class="btn btn-primary btn-lg" onclick="practiceState={active:false,current:0,questions:[],score:0,correct:0};renderTab();renderTodaySection();">完成</button>';
  html += '</div>';
  html += '</div>';

  document.getElementById('tab-content').innerHTML = html;

  if (percent >= 80) triggerConfetti();
}

// ======== 积分闯关模块 ========
