  html += '</div>';

  // 奖励商城
  html += '<div class="card">';
  html += '<div class="card-title">';
  html += '<svg viewBox="0 0 24 24" fill="none" stroke="var(--orange)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 12V8H6a2 2 0 0 1-2-2V4h16"/><path d="M6 12v8a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2v-8"/><circle cx="9" cy="21" r="1"/><circle cx="17" cy="21" r="1"/></svg>';
  html += '积分商城';
  html += '</div>';

  var rewards = points.rewards || [];
  if (rewards.length === 0) {
    html += '<div class="empty-state"><p>还没有奖励，请家长在家长模式中添加</p></div>';
  } else {
    html += '<div class="reward-list">';
    rewards.forEach(function(r) {
      var canAfford = points.total >= r.cost;
      var isClaimed = r.claimed;
      html += '<div class="reward-item' + (isClaimed ? ' claimed' : '') + '">';
      html += '<div class="reward-icon">';
      html += '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>';
      html += '</div>';
      html += '<div class="reward-info">';
      html += '<div class="reward-name">' + r.name + '</div>';
      html += '<div class="reward-cost">' + r.cost + ' 积分</div>';
      html += '</div>';
      if (isClaimed) {
        html += '<button class="reward-btn claimed">已兑换</button>';
      } else if (canAfford) {
        html += '<button class="reward-btn claim" onclick="claimReward(' + r.id + ')">兑换</button>';
      } else {
        html += '<button class="reward-btn disabled">积分不足</button>';
      }
      html += '</div>';
    });
    html += '</div>';
  }
  html += '</div>';

  // 积分记录
  var history = (points.history || []).slice().reverse();
  if (history.length > 0) {
    html += '<div class="card">';
    html += '<div class="points-history-title">积分记录</div>';
    history.slice(0, 10).forEach(function(h) {
      html += '<div class="points-history-item">';
      html += '<span>' + formatDate(h.date) + ' ' + h.action + '</span>';
      html += '<span class="pts">+' + h.points + '</span>';
      html += '</div>';
    });
    html += '</div>';
  }

  return html;
}

function getLevel(totalPoints) {
  for (var i = LEVELS.length - 1; i >= 0; i--) {
    if (totalPoints >= LEVELS[i].min) return LEVELS[i];
  }
  return LEVELS[0];
}

function addPoints(amount, action) {
  var points = loadData(KEYS.points, { total: 0, history: [], rewards: DEFAULT_REWARDS.slice() });
  points.total += amount;
  if (!points.history) points.history = [];
  points.history.push({ date: getTodayStr(), action: action, points: amount });
  saveData(KEYS.points, points);
}

function claimReward(rewardId) {
  var points = loadData(KEYS.points, { total: 0, history: [], rewards: [] });
  var reward = (points.rewards || []).find(function(r) { return r.id === rewardId; });
  if (!reward) return;
  if (reward.claimed) { showToast('已经兑换过了', 'warn'); return; }
  if (points.total < reward.cost) { showToast('积分不够哦', 'error'); return; }

  showConfirm('兑换奖励', '确定要用 ' + reward.cost + ' 积分兑换「' + reward.name + '」吗？', function() {
    points.total -= reward.cost;
    reward.claimed = true;
    saveData(KEYS.points, points);
    showToast('兑换成功！请找家长领取奖励', 'success');
    triggerConfetti();
    renderTab();
    renderTodaySection();
  });
}

function updateRecords(practiceScore) {
  var today = getTodayStr();
  var progress = loadData(KEYS.progress, {});
  var todayProg = progress[today] || {};
  var records = loadData(KEYS.records, []);

  // 更新或添加今天的记录
  var existing = records.find(function(r) { return r.date === today; });
  var learnedCount = todayProg.learned ? todayProg.learned.length : 0;
  var pointsEarned = todayProg.pointsEarned || 0;

  // 获取当前总积分
  var points = loadData(KEYS.points, { total: 0 });

  if (existing) {
    existing.wordsLearned = learnedCount;
    existing.practiceScore = practiceScore;
    existing.pointsEarned = pointsEarned;
    existing.totalPoints = points.total;
  } else {
    records.push({
      date: today,
      wordsLearned: learnedCount,
      practiceScore: practiceScore,
      pointsEarned: pointsEarned,
      totalPoints: points.total
    });
  }
  saveData(KEYS.records, records);
}

// ======== 家长模式 ========
function switchMode(mode) {
  currentMode = mode;
  document.getElementById('tab-child').classList.toggle('active', mode === 'child');
  document.getElementById('tab-parent').classList.toggle('active', mode === 'parent');
  document.getElementById('child-mode').classList.toggle('hidden', mode !== 'child');
  document.getElementById('parent-mode').classList.toggle('hidden', mode !== 'parent');

  if (mode === 'parent') {
    renderParentGate();
  } else {
    renderTodaySection();
    renderTab();
  }
}

function renderParentGate() {
  var settings = loadData(KEYS.settings, {});
  var parentDiv = document.getElementById('parent-mode');

  if (!settings.password) {
    // 首次设置密码
    parentDiv.innerHTML = '';
    var html = '';
    html += '<div class="card parent-gate">';
    html += '<h2>设置家长密码</h2>';
    html += '<p>请设置4位数字密码，进入家长模式时需要输入</p>';
    html += '<div class="parent-gate-input">';
    html += '<input type="password" maxlength="1" id="pwd-1" inputmode="numeric" oninput="onPwdInput(1)">';
    html += '<input type="password" maxlength="1" id="pwd-2" inputmode="numeric" oninput="onPwdInput(2)">';
    html += '<input type="password" maxlength="1" id="pwd-3" inputmode="numeric" oninput="onPwdInput(3)">';
    html += '<input type="password" maxlength="1" id="pwd-4" inputmode="numeric" oninput="onPwdInput(4)">';
    html += '</div>';
    html += '<p style="font-size:13px;color:var(--text-lighter)">密码只是防止宝贝误操作，不是加密安全</p>';
    html += '<button class="btn btn-primary btn-lg" style="margin-top:8px" onclick="setPassword()">确认设置</button>';
    html += '</div>';
    parentDiv.innerHTML = html;
    setTimeout(function() { document.getElementById('pwd-1').focus(); }, 100);
  } else {
    // 输入密码
    parentDiv.innerHTML = '';
    var html2 = '';
    html2 += '<div class="card parent-gate">';
    html2 += '<h2>家长验证</h2>';
    html2 += '<p>请输入4位密码</p>';
    html2 += '<div class="parent-gate-input">';
    html2 += '<input type="password" maxlength="1" id="pwd-1" inputmode="numeric" oninput="onPwdInput(1)">';
    html2 += '<input type="password" maxlength="1" id="pwd-2" inputmode="numeric" oninput="onPwdInput(2)">';
    html2 += '<input type="password" maxlength="1" id="pwd-3" inputmode="numeric" oninput="onPwdInput(3)">';
    html2 += '<input type="password" maxlength="1" id="pwd-4" inputmode="numeric" oninput="onPwdInput(4)">';
    html2 += '</div>';
    html2 += '<button class="btn btn-primary btn-lg" onclick="checkPassword()">进入家长模式</button>';
    html2 += '<button class="btn btn-ghost" style="margin-top:8px" onclick="switchMode(\'child\')">返回宝贝模式</button>';
    html2 += '</div>';
    parentDiv.innerHTML = html2;
    setTimeout(function() { document.getElementById('pwd-1').focus(); }, 100);
  }
}

function onPwdInput(idx) {
  var input = document.getElementById('pwd-' + idx);
  if (input.value && idx < 4) {
    var next = document.getElementById('pwd-' + (idx + 1));
    if (next) next.focus();
  }
  // 自动提交
  if (idx === 4 && input.value) {
    var settings = loadData(KEYS.settings, {});
    if (settings.password) {
      checkPassword();
    } else {
      setPassword();
    }
  }
}

function setPassword() {
  var p1 = document.getElementById('pwd-1').value;
  var p2 = document.getElementById('pwd-2').value;
  var p3 = document.getElementById('pwd-3').value;
  var p4 = document.getElementById('pwd-4').value;
  if (!p1 || !p2 || !p3 || !p4) {
    showToast('请输入完整的4位密码', 'warn');
    return;
  }
  var pwd = p1 + p2 + p3 + p4;
  var settings = loadData(KEYS.settings, {});
  settings.password = pwd;
  saveData(KEYS.settings, settings);
  showToast('密码设置成功！', 'success');
  renderParentDashboard();
}

function checkPassword() {
  var p1 = document.getElementById('pwd-1').value;
  var p2 = document.getElementById('pwd-2').value;
  var p3 = document.getElementById('pwd-3').value;
  var p4 = document.getElementById('pwd-4').value;
  var pwd = p1 + p2 + p3 + p4;
  var settings = loadData(KEYS.settings, {});
  if (pwd === settings.password) {
    renderParentDashboard();
  } else {
    showToast('密码错误，请重试', 'error');
    // 清空输入
    for (var i = 1; i <= 4; i++) {
      document.getElementById('pwd-' + i).value = '';
    }
    document.getElementById('pwd-1').focus();
  }
}

